import { supabase } from './supabase.js';

const session=(await supabase.auth.getSession()).data.session;
if(session)initialize(session.user);

async function initialize(user){
  const {data:ownProfile}=await supabase.from('profiles').select('role').eq('id',user.id).maybeSingle();
  const isAdmin=ownProfile?.role==='admin';
  const widget=document.createElement('section');widget.className='support-widget';widget.innerHTML=`<button class="support-trigger" type="button" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h14v10H9l-4 3V6Z"/></svg><span>Aide</span><b hidden></b></button><div class="support-panel" hidden><header><div><span class="eyebrow">AIDE STOA</span><strong>${isAdmin?'Conversations membres':'Écrire au staff'}</strong></div><button type="button" data-support-close aria-label="Fermer">×</button></header><button class="support-back" type="button" hidden>← Conversations</button><div class="support-content"><p class="support-loading">Ouverture…</p></div><form class="support-form" hidden><label class="sr-only" for="support-message">Votre message</label><textarea id="support-message" rows="2" maxlength="2000" placeholder="Écrivez votre message…" required></textarea><button type="submit" aria-label="Envoyer">→</button></form><p class="support-status" role="status"></p></div>`;document.body.append(widget);
  const trigger=widget.querySelector('.support-trigger'),panel=widget.querySelector('.support-panel'),content=widget.querySelector('.support-content'),form=widget.querySelector('.support-form'),back=widget.querySelector('.support-back'),status=widget.querySelector('.support-status');
  let messages=[],profiles=new Map(),activeMember=isAdmin?null:user.id,channel;
  const esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
  const time=value=>new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
  const loadProfiles=async(ids)=>{const missing=[...new Set(ids)].filter(id=>id&&!profiles.has(id));if(!missing.length)return;const {data}=await supabase.rpc('get_community_profiles',{profile_ids:missing});(data||[]).forEach(item=>profiles.set(item.id,item));};
  const setUnread=()=>{const count=messages.filter(item=>!item.read_at&&item.sender_id!==user.id).length,badge=trigger.querySelector('b');badge.textContent=count>9?'9+':String(count);badge.hidden=!count;};
  const markRead=async()=>{if(panel.hidden)return;const ids=messages.filter(item=>!item.read_at&&item.sender_id!==user.id&&(!isAdmin||item.member_id===activeMember)).map(item=>item.id);if(ids.length){await supabase.from('support_messages').update({read_at:new Date().toISOString()}).in('id',ids);messages.forEach(item=>{if(ids.includes(item.id))item.read_at=new Date().toISOString();});setUnread();}};
  const renderThread=async()=>{const rows=messages.filter(item=>item.member_id===activeMember);await loadProfiles(rows.map(item=>item.sender_id));content.innerHTML=rows.map(item=>{const mine=item.sender_id===user.id,name=mine?'Vous':profiles.get(item.sender_id)?.display_name||'Staff STOA';return `<article class="support-message ${mine?'mine':''}"><span>${esc(name)} · ${time(item.created_at)}</span><p>${esc(item.content).replaceAll('\n','<br>')}</p></article>`;}).join('')||'<p class="support-empty">Posez votre question. Le staff vous répondra ici.</p>';content.scrollTop=content.scrollHeight;form.hidden=false;back.hidden=!isAdmin;await markRead();};
  const renderConversations=async()=>{const memberIds=[...new Set(messages.map(item=>item.member_id))];await loadProfiles(memberIds);content.innerHTML=memberIds.map(id=>{const last=[...messages].reverse().find(item=>item.member_id===id),unread=messages.filter(item=>item.member_id===id&&!item.read_at&&item.sender_id!==user.id).length,p=profiles.get(id);return `<button class="support-conversation" type="button" data-support-member="${id}"><span><strong>${esc(p?.display_name||'Membre STOA')}</strong><small>${esc(last?.content||'')}</small></span>${unread?`<b>${unread}</b>`:''}</button>`;}).join('')||'<p class="support-empty">Aucune demande pour le moment.</p>';form.hidden=true;back.hidden=true;};
  const render=()=>isAdmin&&!activeMember?renderConversations():renderThread();
  const load=async()=>{let query=supabase.from('support_messages').select('*').order('created_at');if(!isAdmin)query=query.eq('member_id',user.id);const {data,error}=await query;if(error){content.innerHTML='<p class="support-empty">La messagerie est momentanément indisponible.</p>';return;}messages=data||[];setUnread();render();};
  const toggle=open=>{panel.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open)render();};
  trigger.addEventListener('click',()=>toggle(panel.hidden));widget.querySelector('[data-support-close]').addEventListener('click',()=>toggle(false));
  content.addEventListener('click',event=>{const button=event.target.closest('[data-support-member]');if(button){activeMember=button.dataset.supportMember;render();}});back.addEventListener('click',()=>{activeMember=null;render();});
  form.addEventListener('submit',async event=>{event.preventDefault();const textarea=form.querySelector('textarea'),value=textarea.value.trim();if(!value||!activeMember)return;form.querySelector('button').disabled=true;const {error}=await supabase.from('support_messages').insert({member_id:activeMember,sender_id:user.id,content:value});form.querySelector('button').disabled=false;status.textContent=error?error.message:'';if(!error){textarea.value='';await load();}});
  await load();channel=supabase.channel(`support:${user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'support_messages'},()=>load()).subscribe();addEventListener('pagehide',()=>{if(channel)supabase.removeChannel(channel)},{once:true});
}
